import { HttpClient } from '@angular/common/http';
import { Component, effect, inject, signal, untracked } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { DatedValue, Session } from '../../core/session';

interface SettingsView {
  /** The highest due a clerk may settle in force on the sheet's today, two decimals; null when there is no limit. */
  clerkLimit: string | null;
  /** The least a claim's live due can be, two decimals. */
  floor: string;
  /** The days after its date a claim is due by. */
  terms: number;
  /** Each grade's own terms in days, by grade; a grade left out uses the sheet's terms. */
  gradeTerms: Record<string, number>;
  /** The percent of its figure an overdue claim's due gains every full 30 days, two decimals. */
  latePct: string;
  /** The date (yyyy-mm-dd) before which a claim rounds half up, and on or after which half to even; null: the today. */
  policyDate: string | null;
  /** The date (yyyy-mm-dd) from which, on the sheet's today, a claim opened is numbered within its period; null: off. */
  periodNumberingFrom: string | null;
  /** The most a person's due-total can be, two decimals; null when there is no cap. */
  cap: string | null;
  /** The days past its to-date after which a change of today closes an open period; null: off. */
  graceDays: number | null;
  /** The due above which a claim cannot be settled or approved without a proof, two decimals; null when there is none. */
  proofThreshold: string | null;
  /** The permission matrix, by action: the roles that may take it, comma separated; null: the standing rule. */
  permissions: Record<string, string | null>;
  /** Every value recorded of each dated setting, by key, from-date first to last. */
  dated: Record<string, DatedValue[]>;
-- A third role, viewer: sees everything on the sheet and may change nothing.
CREATE TABLE sheet_role_new (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(100) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('clerk', 'steward', 'viewer'))
);
INSERT INTO sheet_role_new (id, sheet_id, user_name, role) SELECT id, sheet_id, user_name, role FROM sheet_role;
DROP TABLE sheet_role;
ALTER TABLE sheet_role_new RENAME TO sheet_role;
ALTER TABLE sheet_role ALTER COLUMN id RESTART WITH (SELECT COALESCE(MAX(id), 0) + 1 FROM sheet_role);
CREATE UNIQUE INDEX sheet_role_user ON sheet_role (sheet_id, user_name);
-- The permission matrix: for an action (open, settle, void, reassign, close, reopen), the roles that may take it, as
-- a comma separated list (clerk, steward). Not dated. An action with no row keeps the standing rule: open, settle,
-- void and close by clerk and steward; reassign and reopen by steward.
CREATE TABLE sheet_permission (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    action   VARCHAR(20)  NOT NULL,
    roles    VARCHAR(100) NOT NULL,
    PRIMARY KEY (sheet_id, action)
);
-- The users watching a person, each at most once. A watcher is told (a NOTIFY record) whenever a claim of the person
-- is settled, approved or re-settled; watchers are told in the order they started watching.
CREATE TABLE person_watch (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    user_name VARCHAR(100) NOT NULL
);
CREATE UNIQUE INDEX person_watch_pair ON person_watch (person_id, user_name);
CREATE INDEX person_watch_sheet ON person_watch (sheet_id, user_name);
